import{z as r,x as p,o,c as A,q as l,j as t,D as e,d as E,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"网卡驱动与 NAPI","description":"","frontmatter":{"title":"网卡驱动与 NAPI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/napi.md","filePath":"cs/napi.md","lastUpdated":1791413859000}'),B={name:"cs/napi.md"};function d(c,a,_,P,D,u){const i=p("Mermaid");return o(),A("div",null,[a[2]||(a[2]=l('<h1 id="网卡驱动与-napi" tabindex="-1">网卡驱动与 NAPI <a class="header-anchor" href="#网卡驱动与-napi" aria-label="Permalink to &quot;网卡驱动与 NAPI&quot;">​</a></h1><div class="epigraph"><p>NAPI 在第一包用中断叫醒，随后关中断、在软中断里轮询收包，直到配额用尽或队列空再开中断。</p><footer>—— 据 Salim, Olsson, Kuznetsov, Beyond Softnet；Linux NAPI 文档</footer></div><p><a href="/cs/skbuff">上一课</a>有了包对象。若每帧一个硬中断，万兆上会 livelock：<a href="/cs/io-polling">轮询 I/O</a> 在存储侧已见过同一税。缺口是 <strong>NAPI</strong>：Linux 网卡的混合中断/轮询。本课不把 XDP 提前展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>livelock：CPU 全在 IRQ 里建 skb，协议层得不到时间。NAPI：驱动注册 <code>napi_struct</code>，IRQ 只 <code>napi_schedule</code>，<code>poll()</code> 从环形缓冲取描述符、填 skb、<code>netif_receive_skb</code>。配额（weight）防止一网卡饿死调度。缺口：多队列网卡每队列一个 NAPI；忙时类似存储 poll，闲时仍靠 IRQ 省电。</p><p><span class="marginnote">直觉类比：NAPI 像「前厅取餐」——第一单来电话叫你（中断），发现生意忙，你干脆站到窗口一批一批地取（轮询），直到窗口没人了才回工位继续等电话。若每单都接一次电话（每帧一个中断），高峰期你只会被铃声淹死，一份餐都出不了。</span></p><p><span class="marginnote">busy polling（<code>SO_BUSY_POLL</code>）让用户线程直接调 napi poll，与存储 IOPOLL 同构。本课先钉内核软中断路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开中断 → 来包 → 关该队列 IRQ → 软中断 <code>net_rx_action</code> 调 poll → 上送协议栈 → 若工作仍多则再排 NAPI。对照 NVMe poll：一个是块 CQ，一个是 NIC ring。对照 <a href="/cs/blkio-cgroup">blkio</a>：包的节流在 qdisc/cgroup net，不在 NAPI 配额里。</p>',9)),(o(),t(n,null,{default:e(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SCH%5B%22napi_schedule%22%5D%0A%20%20SCH%20--%3E%20POLL%5B%22poll%20%E6%94%B6%E7%8E%AF%22%5D%0A%20%20POLL%20--%3E%20SKB%5B%22%E5%BB%BA%20sk_buff%22%5D%0A%20%20SKB%20--%3E%20RX%5B%22netif_receive_skb%22%5D%0A%20%20POLL%20--%3E%7C%22%E7%A9%BA%E9%97%B2%22%7C%20EI%5B%22%E9%87%8D%E6%96%B0%E5%BC%80%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NAPI 把「包到达」从逐帧 IRQ 换成批量，使协议栈与应用能跑。它是 Linux 网络性能的底座，后课 GRO 在 poll 里聚合。不要写成实时保证：软中断仍抢占用户，过重会 raise <code>ksoftirqd</code>。</p><p><span class="marginnote">数字实例：万兆以太网发 64 字节小包的线速约 1488 万包/秒。逐帧中断意味着每秒近 1500 万次中断，光响应铃声就能吃满一个核（正是 livelock）；NAPI 改成一次 poll 取一批（比如 64 个包），中断次数直接降到每秒二十几万次调度级别。</span></p><p><span class="marginnote">常见误区：初学者以为 NAPI 是「纯轮询」或某种实时保证。实际上空闲时它仍关不掉中断——靠 IRQ 叫醒才省电；软中断也不承诺延迟上限，负载过重时内核会唤醒 <code>ksoftirqd</code> 线程接手，交互进程照样可能感到抖动。</span></p><p>与设备模型：网卡仍是 PCI 设备，本课只管收包引擎。</p><p>实现上：weight 用尽会让出 softirq，避免一网卡饿死调度。RPS 把包再丢到别的 CPU 的 backlog，等于软件 RSS。busy poll 让套接字在 recv 里直接 napi_poll。 读法上只引用<a href="/cs/skbuff">上一课</a>的结论，不把对象换成训练推理或限价簿。</p>',6)),(o(),t(n,null,{default:e(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20POLL%5B%22poll%20%E4%B8%80%E6%89%B9%E5%8C%85%22%5D%20--%3E%20Q%7B%22%E9%85%8D%E9%A2%9D%EF%BC%88weight%EF%BC%89%E7%94%A8%E5%B0%BD%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9C%AA%E7%94%A8%E5%B0%BD%22%7C%20MORE%5B%22%E7%BB%A7%E7%BB%AD%E6%94%B6%E4%B8%8B%E4%B8%80%E6%89%B9%22%5D%0A%20%20Q%20--%3E%7C%22%E7%94%A8%E5%B0%BD%22%7C%20YIELD%5B%22%E8%AE%A9%E5%87%BA%20softirq%EF%BC%8C%E9%87%8D%E6%96%B0%E6%8E%92%20NAPI%22%5D%0A%20%20YIELD%20--%3E%20APP%5B%22%E5%8D%8F%E8%AE%AE%E6%A0%88%E4%B8%8E%E5%BA%94%E7%94%A8%E5%88%86%E5%88%B0%20CPU%22%5D%0A%20%20Q%20--%3E%7C%22%E9%98%9F%E5%88%97%E7%A9%BA%22%7C%20REIRQ%5B%22%E9%87%8D%E5%BC%80%E4%B8%AD%E6%96%AD%EF%BC%8C%E5%9B%9E%E7%9C%81%E7%94%B5%E5%BE%85%E5%91%BD%22%5D%0A%20%20OVER%5B%22%E8%B4%9F%E8%BD%BD%E6%8C%81%E7%BB%AD%E8%BF%87%E9%87%8D%22%5D%20--%3E%20K%5B%22ksoftirqd%20%E7%BA%BF%E7%A8%8B%E6%8E%A5%E6%89%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>网卡驱动与 NAPI</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 ethtool coalescing 参数。不保证无线驱动的 NAPI 形状相同。下一课在 poll 里把小包粘成大段：GRO，以及发送侧的 GSO。</p><p>版本字段会变，课序钉的是机制对象「网卡驱动与 NAPI」，不是某一主线内核的结构体名。 后课默认：收包走 NAPI 轮询配额。分段卸载与聚合，下一课 GRO/GSO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NAPI：首包中断，随后轮询收环，用配额限时。</li><li>多队列对应多个 napi_struct。</li><li>GRO/GSO 是下一课。</li><li>出处：Salim et al.；Linux NAPI；Benvenuti <em>ULNI</em>。</li></ul>',7))])}const h=r(B,[["render",d]]);export{f as __pageData,h as default};
